        if len(lst) == 4:
            return lst[0] * 2 * 2 * 2

        if len(lst) == 5:
            return lst[0] * 2 * 2 * 2 * 2

        return []


    def divisible_by_40(num):
        return num % 40 == 0


    result = []
    for num in x:
        if keep_deep(num) != []:
            result.append(keep_deep(num))
        else:
