def nested_op(x):
    """
    Keeps only the integers divisible by 28, then keeps only the integers at depth 4 or deeper,
    and returns the number of distinct even results.

    Args:
        x (list): An arbitrarily nested list of integers.

    Returns:
        int: The number of distinct even results.
    """
    distinct_even = set()
    count = 0
    stack = []

    for item in x:
        if isinstance(item, int):
            if item % 28 == 0:
                distinct_even.add(item)
                count += 1
        elif isinstance(item, list):
            if item:
                stack.append(item)
                while len(stack) > 0 and isinstance(stack[-1], list):
                    stack.pop()
                if isinstance(stack[-1], list):
                    stack.append(item)
        else:
            continue

    return len(distinct_even)
